import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { apiGet, apiDelete } from "../utils/api";

const PersonTable = () => {
    const [persons, setPersons] = useState([]);
    const [page, setPage] = useState(0);
    const [size, setSize] = useState(10);
    const [totalPages, setTotalPages] = useState(1);

    const loadPersons = () => {
        apiGet("/persons", { page, size })
            .then((data) => {
                setPersons(data); // API vrací přímo pole dat
                setTotalPages(Math.ceil(data.length / size)); // Stránkování podle velikosti pole
            })
            .catch((error) => console.error("Chyba při načítání dat:", error));
    };

    useEffect(() => {
        loadPersons();
    }, [page, size]);

    const deletePerson = (id) => {
        apiDelete(`/persons/${id}`)
            .then(() => {
                loadPersons(); // Znovu načteme seznam po smazání
            })
            .catch((error) => console.error("Chyba při mazání:", error));
    };

    return (
        <div>
            <p>Seznam osob ({persons.length})</p>

            <table className="table table-bordered">
                <thead>
                    <tr>
                        <th>#</th>
                        <th>Jméno</th>
                        <th>Akce</th>
                    </tr>
                </thead>
                <tbody>
                    {persons.map((item, index) => (
                        <tr key={item._id}>
                            <td>{index + 1 + page * size}</td>
                            <td>{item.name}</td>
                            <td>
                                <div className="btn-group">
                                    <Link to={`/persons/show/${item._id}`} className="btn btn-sm btn-info">
                                        Zobrazit
                                    </Link>
                                    <Link to={`/persons/edit/${item._id}`} className="btn btn-sm btn-warning">
                                        Upravit
                                    </Link>
                                    <button onClick={() => deletePerson(item._id)} className="btn btn-sm btn-danger">
                                        Odstranit
                                    </button>
                                </div>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>

            {/* Stránkování */}
            <div className="pagination">
                <button 
                    className="btn btn-primary" 
                    disabled={page === 0} 
                    onClick={() => setPage(page - 1)}
                >
                    Předchozí
                </button>
                <span style={{ margin: "0 10px" }}>Strana {page + 1} / {totalPages}</span>
                <button 
                    className="btn btn-primary" 
                    disabled={page >= totalPages - 1} 
                    onClick={() => setPage(page + 1)}
                >
                    Další
                </button>
                <select onChange={(e) => setSize(Number(e.target.value))} value={size} className="ml-3">
                    <option value="5">5</option>
                    <option value="10">10</option>
                    <option value="20">20</option>
                </select>
            </div>

            <Link to="/persons/create" className="btn btn-success mt-3">
                Nová osoba
            </Link>
        </div>
    );
};

export default PersonTable;
